(function () {
  'use strict';

  var STORAGE_KEY = 'todos-javascript';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  // ---------- Model ----------

  function Todo(title) {
    this.id = Date.now() + Math.random();
    this.title = title;
    this.completed = false;
  }

  function TodoModel() {
    this.todos = this.load();
  }

  TodoModel.prototype.load = function () {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  };

  TodoModel.prototype.save = function () {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
  };

  TodoModel.prototype.add = function (title) {
    var todo = new Todo(title);
    this.todos.push(todo);
    this.save();
    return todo;
  };

  TodoModel.prototype.remove = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.save();
  };

  TodoModel.prototype.toggle = function (id) {
    var todo = this.todos.find(function (t) { return t.id === id; });
    if (todo) { todo.completed = !todo.completed; this.save(); }
  };

  TodoModel.prototype.toggleAll = function (completed) {
    this.todos.forEach(function (t) { t.completed = completed; });
    this.save();
  };

  TodoModel.prototype.clearCompleted = function () {
    this.todos = this.todos.filter(function (t) { return !t.completed; });
    this.save();
  };

  TodoModel.prototype.update = function (id, title) {
    var todo = this.todos.find(function (t) { return t.id === id; });
    if (todo) { todo.title = title; this.save(); }
  };

  TodoModel.prototype.getActive = function () {
    return this.todos.filter(function (t) { return !t.completed; });
  };

  TodoModel.prototype.getCompleted = function () {
    return this.todos.filter(function (t) { return t.completed; });
  };

  // ---------- Controller ----------

  function TodoController(model) {
    this.model = model;
    this.filter = 'all';
    this.editingId = null;
    this.bindEvents();
    this.render();
  }

  TodoController.prototype.bindEvents = function () {
    var self = this;

    document.querySelector('.new-todo').addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
        var val = e.target.value.trim();
        if (val) {
          self.model.add(val);
          e.target.value = '';
          self.render();
        }
      }
    });

    document.querySelector('.todo-list').addEventListener('click', function (e) {
      var li = e.target.closest('li');
      if (!li) return;
      var id = Number(li.dataset.id);

      if (e.target.classList.contains('toggle')) {
        self.model.toggle(id);
        self.render();
      }

      if (e.target.classList.contains('destroy')) {
        self.model.remove(id);
        self.render();
      }
    });

    document.querySelector('.todo-list').addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (!label) return;
      var li = label.closest('li');
      if (!li) return;
      self.editTodo(li);
    });

    document.querySelector('.todo-list').addEventListener('focusout', function (e) {
      if (e.target.classList.contains('edit')) {
        self.commitEdit(e.target);
      }
    });

    document.querySelector('.todo-list').addEventListener('keydown', function (e) {
      if (e.target.classList.contains('edit')) {
        if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
          e.target.blur();
        } else if (e.keyCode === ESCAPE_KEY || e.key === 'Escape') {
          self.cancelEdit(e.target);
        }
      }
    });

    document.getElementById('toggle-all').addEventListener('change', function (e) {
      self.model.toggleAll(e.target.checked);
      self.render();
    });

    document.querySelector('.clear-completed').addEventListener('click', function () {
      self.model.clearCompleted();
      self.render();
    });

    window.addEventListener('hashchange', function () {
      self.route();
      self.render();
    });

    this.route();
  };

  TodoController.prototype.route = function () {
    var hash = window.location.hash;
    if (hash === '#/active') this.filter = 'active';
    else if (hash === '#/completed') this.filter = 'completed';
    else this.filter = 'all';
  };

  TodoController.prototype.editTodo = function (li) {
    var id = Number(li.dataset.id);
    this.editingId = id;
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.value = li.querySelector('label').textContent;
    editInput.focus();
  };

  TodoController.prototype.commitEdit = function (input) {
    var li = input.closest('li');
    if (!li) return;
    var id = Number(li.dataset.id);
    var val = input.value.trim();
    if (val) {
      this.model.update(id, val);
    } else {
      this.model.remove(id);
    }
    this.editingId = null;
    this.render();
  };

  TodoController.prototype.cancelEdit = function (input) {
    var li = input.closest('li');
    if (!li) return;
    li.classList.remove('editing');
    this.editingId = null;
    input.value = li.querySelector('label').textContent;
  };

  TodoController.prototype.render = function () {
    var self = this;
    var todos = this.model.todos;
    var list = document.querySelector('.todo-list');
    var main = document.querySelector('.main');
    var footer = document.querySelector('.footer');
    var countEl = document.querySelector('.todo-count');
    var clearBtn = document.querySelector('.clear-completed');
    var toggleAll = document.getElementById('toggle-all');

    var filtered = todos;
    if (this.filter === 'active') filtered = this.model.getActive();
    else if (this.filter === 'completed') filtered = this.model.getCompleted();

    list.innerHTML = filtered.map(function (todo) {
      var checked = todo.completed ? 'checked' : '';
      var completedClass = todo.completed ? 'completed' : '';
      var editingClass = self.editingId === todo.id ? 'editing' : '';
      return '<li class="' + completedClass + ' ' + editingClass + '" data-id="' + todo.id + '">' +
        '<div class="view">' +
        '<input class="toggle" type="checkbox" ' + checked + '>' +
        '<label>' + todo.title + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + todo.title.replace(/"/g, '&quot;') + '">' +
        '</li>';
    }).join('');

    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? '' : 'none';
    footer.style.display = hasTodos ? '' : 'none';

    var activeCount = this.model.getActive().length;
    var word = activeCount === 1 ? 'item' : 'items';
    countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    var completedCount = this.model.getCompleted().length;
    clearBtn.style.display = completedCount > 0 ? '' : 'none';

    toggleAll.checked = todos.length > 0 && activeCount === 0;

    var filterLinks = document.querySelectorAll('.filters a');
    filterLinks.forEach(function (a) {
      a.classList.remove('selected');
      var href = a.getAttribute('href');
      if ((self.filter === 'all' && href === '#/') ||
          (self.filter === 'active' && href === '#/active') ||
          (self.filter === 'completed' && href === '#/completed')) {
        a.classList.add('selected');
      }
    });
  };

  // ---------- Init ----------

  var model = new TodoModel();
  var controller = new TodoController(model);

  // Allow the verification harness to trigger a re-load from localStorage
  window.addEventListener('app-reload', function () {
    model.todos = model.load();
    controller.filter = window.location.hash === '#/active' ? 'active'
      : window.location.hash === '#/completed' ? 'completed'
      : 'all';
    controller.render();
  });
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then } = require('@cucumber/cucumber');
const { assert } = require('console');

// =============================================================================
// Helper functions
// =============================================================================

function getTodoList(world) {
  return Array.from(world.document.querySelectorAll('.todo-list li'));
}

function findTodoItem(world, title) {
  return getTodoList(world).find(
    (li) => li.querySelector('.view label')?.textContent === title
  );
}

function findTodoIndex(world, title) {
  return getTodoList(world).findIndex(
    (li) => li.querySelector('.view label')?.textContent === title
  );
}

function getTodoTitle(li) {
  return li.querySelector('.view label')?.textContent ?? '';
}

function getTodosFromLocalStorage(world) {
  try {
    const data = world.localStorage.getItem('todos-javascript');
    return data ? JSON.parse(data) : [];
  } catch {
    return [];
  }
}

function setTodosToLocalStorage(world, todos) {
  world.localStorage.setItem('todos-javascript', JSON.stringify(todos));
}

function parseTodoListArg(arg) {
  if (typeof arg === 'string') return [arg];
  // Cucumber datatable or multiple strings
  if (Array.isArray(arg)) return arg;
  return [String(arg)];
}

// Create a list item by dispatching through the app's new-todo input
function addTodoViaInput(world, title) {
  const input = world.document.querySelector('.new-todo');
  if (!input) return;
  input.value = title;
  const keydown = new world.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true });
  input.dispatchEvent(keydown);
}

// Toggle completion status on a todo by clicking its checkbox
function setTodoCompleted(world, title, completed) {
  const li = findTodoItem(world, title);
  if (!li) return;
  if (completed) {
    if (!li.classList.contains('completed')) {
      const checkbox = li.querySelector('.toggle');
      if (checkbox) checkbox.click();
    }
  } else {
    if (li.classList.contains('completed')) {
      const checkbox = li.querySelector('.toggle');
      if (checkbox) checkbox.click();
    }
  }
}

// =============================================================================
// Given steps
// =============================================================================

Given('the app is loaded', function () {
  // Handled by Before hook in world.js - app is already loaded
});

Given('there are no todos', function () {
  // Clear localStorage and trigger app to re-read from empty storage
  this.localStorage.removeItem('todos-javascript');
  if (this.window) {
    this.window.dispatchEvent(new this.window.Event('app-reload'));
  }
});

Given('the todo list contains {string}', function (title) {
  addTodoViaInput(this, title);
});

Given('the todo list contains {string}, {string}', function (title1, title2) {
  addTodoViaInput(this, title1);
  addTodoViaInput(this, title2);
});

Given('the todo list contains {string}, {string}, {string}', function (title1, title2, title3) {
  addTodoViaInput(this, title1);
  addTodoViaInput(this, title2);
  addTodoViaInput(this, title3);
});

Given('the todo list contains a completed todo {string}', function (title) {
  addTodoViaInput(this, title);
  // Now toggle it to completed
  setTodoCompleted(this, title, true);
});

Given('{string} is completed', function (title) {
  setTodoCompleted(this, title, true);
});

Given('all todos are completed', function () {
  var todos = getTodosFromLocalStorage(this);
  // Create default todos if there are none
  if (todos.length === 0) {
    var defaultTitles = ['Buy milk', 'Walk dog', 'Write code'];
    var nextId = 1;
    defaultTitles.forEach(function(title) {
      todos.push({ id: nextId++, title: title, completed: true });
    });
  } else {
    todos.forEach(function(t) { t.completed = true; });
  }
  setTodosToLocalStorage(this, todos);
  if (this.window) {
    this.window.dispatchEvent(new this.window.Event('app-reload'));
  }
});

Given('I am editing the {string} item', function (title) {
  const li = findTodoItem(this, title);
  if (li) {
    const label = li.querySelector('.view label');
    if (label) {
      const dblClick = new this.window.MouseEvent('dblclick', { bubbles: true });
      label.dispatchEvent(dblClick);
    }
  }
});

Given('localStorage contains a todo with title {string}', function (title) {
  const todos = getTodosFromLocalStorage(this);
  const newId = todos.length > 0 ? Math.max(...todos.map((t) => t.id)) + 1 : 1;
  todos.push({ id: newId, title: title, completed: false });
  setTodosToLocalStorage(this, todos);
  // Trigger app to re-read from localStorage
  if (this.window) {
    this.window.dispatchEvent(new this.window.Event('app-reload'));
  }
});

Given('localStorage contains a completed todo with title {string}', function (title) {
  const todos = getTodosFromLocalStorage(this);
  const newId = todos.length > 0 ? Math.max(...todos.map((t) => t.id)) + 1 : 1;
  todos.push({ id: newId, title: title, completed: true });
  setTodosToLocalStorage(this, todos);
  // Trigger app to re-read from localStorage
  if (this.window) {
    this.window.dispatchEvent(new this.window.Event('app-reload'));
  }
});

Given('the current route is {string}', function (route) {
  if (this.window && this.window.location) {
    this.window.location.hash = route;
  }
});

Given('the All filter link has the selected class', function () {
  const links = this.document.querySelectorAll('.filters a');
  links.forEach((a) => a.classList.remove('selected'));
  const allLink = this.document.querySelector('.filters a[href="#/"]');
  if (allLink) allLink.classList.add('selected');
});

// =============================================================================
// When steps
// =============================================================================

When('I type {string} in the new-todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  if (input) {
    input.value = text;
    const event = new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true });
    input.dispatchEvent(event);
    // Also fire keydown + keyup for robustness
    const keydown = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true });
    input.dispatchEvent(keydown);
    const keyup = new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true });
    input.dispatchEvent(keyup);
  }
});

When('I click the toggle checkbox on the {string} item', function (title) {
  const li = findTodoItem(this, title);
  if (li) {
    const checkbox = li.querySelector('.toggle');
    if (checkbox) {
      checkbox.click();
    }
  }
});

When('I click the toggle checkbox on {string}', function (title) {
  const li = findTodoItem(this, title);
  if (li) {
    const checkbox = li.querySelector('.toggle');
    if (checkbox) {
      checkbox.click();
    }
  }
});

When('I click the destroy button on the {string} item', function (title) {
  const li = findTodoItem(this, title);
  if (li) {
    const destroyBtn = li.querySelector('.destroy');
    if (destroyBtn) destroyBtn.click();
  }
});

When('I click the toggle-all checkbox', function () {
  const checkbox = this.document.getElementById('toggle-all');
  if (checkbox) {
    checkbox.click();
  }
});

When('I click the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) btn.click();
});

When('I double-click the label of the {string} item', function (title) {
  const li = findTodoItem(this, title);
  if (li) {
    const label = li.querySelector('.view label');
    if (label) {
      const dblClick = new this.window.MouseEvent('dblclick', { bubbles: true });
      label.dispatchEvent(dblClick);
    }
  }
});

When('I change the edit input to {string} and press Enter', function (newTitle) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    const editInput = editingLi.querySelector('.edit');
    if (editInput) {
      editInput.value = newTitle;
      const enterEvent = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true });
      editInput.dispatchEvent(enterEvent);
    }
  }
});

When('I change the edit input to {string} and the input loses focus', function (newTitle) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    const editInput = editingLi.querySelector('.edit');
    if (editInput) {
      editInput.value = newTitle;
      // Dispatch focusout (bubbles) which is what the app listens for
      const focusOutEvent = new this.window.FocusEvent('focusout', { bubbles: true });
      editInput.dispatchEvent(focusOutEvent);
    }
  }
});

When('I change the edit input to {string}', function (newTitle) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    const editInput = editingLi.querySelector('.edit');
    if (editInput) {
      editInput.value = newTitle;
    }
  }
});

When('I press the Escape key', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (editingLi) {
    const editInput = editingLi.querySelector('.edit');
    if (editInput) {
      const escapeEvent = new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true });
      editInput.dispatchEvent(escapeEvent);
    }
  }
});

When('I navigate to {string}', function (route) {
  if (this.navigate) {
    this.navigate(route);
  }
});

When('I reload the app', function () {
  // Trigger the app to re-read from localStorage via custom event
  if (this.window) {
    this.window.dispatchEvent(new this.window.Event('app-reload'));
  }
});

// =============================================================================
// Then steps
// =============================================================================

Then('the main section should not be visible', function () {
  const main = this.document.querySelector('.main');
  const style = main.style.display || '';
  if (style !== 'none') {
    // Also check computed style
    const computed = this.window.getComputedStyle(main);
    if (computed.display !== 'none') {
      throw new Error('Expected main section to not be visible, but it was visible');
    }
  }
});

Then('the footer should not be visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = footer.style.display || '';
  if (style !== 'none') {
    const computed = this.window.getComputedStyle(footer);
    if (computed.display !== 'none') {
      throw new Error('Expected footer to not be visible, but it was visible');
    }
  }
});

Then('the todo list should be empty', function () {
  const items = getTodoList(this);
  if (items.length !== 0) {
    throw new Error('Expected empty todo list but found ' + items.length + ' items');
  }
});

Then('the todo list should contain {int} item', function (count) {
  const items = getTodoList(this);
  if (items.length !== count) {
    throw new Error('Expected ' + count + ' item(s) but found ' + items.length);
  }
});

Then('the todo list should contain {int} items', function (count) {
  const items = getTodoList(this);
  if (items.length !== count) {
    throw new Error('Expected ' + count + ' items but found ' + items.length);
  }
});

Then('the new item should be labelled {string}', function (expectedTitle) {
  const items = getTodoList(this);
  if (items.length === 0) {
    throw new Error('Expected a new todo item but list is empty');
  }
  const lastItem = items[items.length - 1];
  const label = lastItem.querySelector('.view label');
  if (!label || label.textContent !== expectedTitle) {
    throw new Error(
      'Expected new item to be labelled "' + expectedTitle + '" but got "' + (label ? label.textContent : 'none') + '"'
    );
  }
});

Then('the new-todo input should be cleared', function () {
  const input = this.document.querySelector('.new-todo');
  if (input && input.value !== '') {
    throw new Error('Expected new-todo input to be cleared but got "' + input.value + '"');
  }
});

Then('the {string} item should have the completed class', function (title) {
  const li = findTodoItem(this, title);
  if (!li) {
    throw new Error('Could not find todo item "' + title + '"');
  }
  if (!li.classList.contains('completed')) {
    throw new Error('Expected "' + title + '" to have completed class');
